{
  "version": 1,
  "retired": []
}

/* Atelier Montres · genuine-watch photographic viewer */
.am-photo-dialog{position:fixed;inset:0;width:min(1020px,calc(100vw - 30px));max-width:1020px;max-height:min(95dvh,950px);margin:auto;padding:0;border:1px solid #c6ae83;background:#f8f6ef;color:#20392a;box-shadow:0 32px 90px #09150cc2;overflow:auto;overscroll-behavior:contain}
.am-photo-dialog::backdrop{background:#07120bd9;backdrop-filter:blur(7px)}
.am-photo-top{padding:17px 24px;background:#172e22;color:#fff;display:flex;align-items:center;justify-content:space-between;gap:16px}
.am-photo-meta{min-width:0}
.am-photo-kicker{font:700 9px/1.4 system-ui,sans-serif;letter-spacing:.2em;color:#d8b987;margin:0 0 5px}
.am-photo-title{font:400 clamp(19px,3vw,30px)/1.2 Georgia,serif;color:#fff;overflow-wrap:anywhere;margin:0}
.am-photo-close{width:44px;height:44px;flex:none;border:1px solid #e1cfaf66;border-radius:50%;background:transparent;color:#fff;font:400 30px/1 system-ui;cursor:pointer}
.am-photo-canvas{height:clamp(300px,59dvh,650px);background:radial-gradient(circle at center,#fffefa 0%,#eeeae1 80%);position:relative;display:flex;align-items:center;justify-content:center;overflow:auto;overscroll-behavior:contain;padding:16px}
 .am-photo-large{width:auto;height:auto;max-height:100%;max-width:100%;object-fit:contain;mix-blend-mode:multiply;filter:drop-shadow(0 15px 25px #071c1324);transition:width .18s ease,max-width .18s ease}
 .am-photo-canvas.am-photo-expanded{justify-content:flex-start;align-items:flex-start}
/* Prevent the image from shrinking to the flex viewport: enlarged details must
   really be scrollable, not just a cosmetic button state. */
.am-photo-canvas.am-photo-expanded .am-photo-large{flex:0 0 auto;max-width:none;max-height:none;width:200%;height:auto;margin:0}
 .am-photo-large:not([hidden]){cursor:zoom-in}
.am-photo-canvas.am-photo-expanded .am-photo-large{cursor:zoom-out}
.am-photo-status{max-width:250px;text-align:center;font-size:13px;color:#617063}
.am-photo-bottom{display:flex;align-items:center;justify-content:center;gap:10px;flex-wrap:wrap;padding:17px 22px 8px}
.am-photo-bottom button,.am-photo-official{font:650 12px system-ui,sans-serif;border:1px solid #c9c2b3;background:#fffefa;color:#23432f;padding:11px 15px;min-height:44px;cursor:pointer;border-radius:2px;text-decoration:none}
.am-photo-bottom button:hover,.am-photo-official:hover{background:#e7e8df}
.am-photo-bottom button:disabled{opacity:.4;cursor:default}
.am-photo-bottom [hidden]{display:none!important}
.am-photo-position{font-size:12px;letter-spacing:.12em;color:#6d756e;min-width:43px;text-align:center}
.am-photo-official{background:#244532;color:#fff;border-color:#244532}
.am-photo-official:hover{background:#315740;color:#fff}
.am-photo-note{padding:0 24px 14px;color:#737b71;font-size:10px;line-height:1.6;text-align:center;margin:5px 0 0}
.aff-illustration{overflow:hidden}
.aff-photo-expand{position:absolute;inset:0;z-index:4;border:0;background:transparent;color:#263f31;cursor:zoom-in;display:flex;align-items:flex-end;justify-content:flex-end;padding:14px}
.aff-photo-expand span{background:#fffefaeb;border:1px solid #e0d6c6;padding:8px 11px;box-shadow:0 4px 12px #14231b16;font:700 10px system-ui,sans-serif;letter-spacing:.03em}
.aff-photo-expand:hover span,.aff-photo-expand:focus-visible span{background:#244532;color:#fff}
.aff-photo-expand:focus-visible{outline:3px solid #d7af70;outline-offset:-3px}
.aff-card .aff-illustration:has(.aff-photo-expand) .aff-art-label{pointer-events:none}
.detail-photo-expand{min-height:44px;border:1px solid #c2b79f;background:#fffdf7;color:#234531;font:700 12px system-ui,sans-serif;padding:12px 18px;cursor:zoom-in;margin:12px 0 2px}
.detail-photo-expand:hover{background:#294c36;color:#fff}
@media(max-width:650px){
 .am-photo-dialog{width:calc(100vw - 12px);max-height:96dvh}
 .am-photo-top{padding:12px 14px}
 .am-photo-canvas{height:clamp(280px,54dvh,560px)}
 .am-photo-bottom{position:sticky;bottom:0;z-index:2;gap:7px;padding:12px 9px 11px;background:#f8f6ef;border-top:1px solid #ded7c9;box-shadow:0 -8px 20px #172e2212}
 .am-photo-bottom button,.am-photo-official{font-size:11px;padding:9px 11px}
 .am-photo-note{padding-inline:12px}
}
@media(prefers-reduced-motion:reduce){.am-photo-large{transition:none}}

'use strict';
/* One locally sourced, keyboard- and touch-accessible photographic viewer. */
(() => {
  if (window.AtelierPhoto) return;
  const el=(tag,cls,label)=>{
    const n=document.createElement(tag);
    if(cls)n.className=cls;
    if(label!==undefined)n.textContent=label;
    return n;
  };
  let items=[],index=0,loaded=false,expanded=false,initialTouch=null,assetPrefix='./';
  const dialog=el('dialog','am-photo-dialog');
  dialog.id='amPhotoDialog';
  dialog.setAttribute('aria-label','Visionneuse de photographies des montres');
  const top=el('div','am-photo-top'),meta=el('div','am-photo-meta');
  const kicker=el('p','am-photo-kicker','PHOTOGRAPHIE DU MODÈLE');
  const title=el('h2','am-photo-title');
  const close=el('button','am-photo-close','×');
  close.type='button';close.setAttribute('aria-label','Fermer la photo');
  meta.append(kicker,title);top.append(meta,close);
  const canvas=el('div','am-photo-canvas');
  const photo=el('img','am-photo-large');
  photo.alt='';photo.decoding='async';photo.loading='eager';
  const message=el('p','am-photo-status','Chargement de la photographie…');
  message.setAttribute('role','status');
  canvas.append(photo,message);
  const bottom=el('div','am-photo-bottom');
  const prev=el('button','am-photo-prev','← Précédente');
  const next=el('button','am-photo-next','Suivante →');
  const zoom=el('button','am-photo-zoom','Agrandir ×2');
  const position=el('span','am-photo-position');
  const link=el('a','am-photo-official','Fiche fabricant ↗');
  link.target='_blank';link.rel='noopener noreferrer nofollow';
  for(const b of [prev,next,zoom]) b.type='button';
  bottom.append(prev,position,next,zoom,link);
  const note=el('p','am-photo-note','Photographies des références déclarées autorisées par l’éditeur, sans vérification indépendante des licences. Images et prix non contractuels.');
  dialog.append(top,canvas,bottom,note);
  const source=p=>{
    const t=p.photoReview||{};
    if(t.publicUsageApproved!==true)return null;
    // Do not load a research URL outside this site when the local photo fails.
    if(!/^[a-z0-9-]{4,64}$/.test(p.id))return null;
    const allowed=['./assets/watches/'+p.id+'.webp',
      './assets/watches-popular/'+p.id+'.webp'];
    return allowed.includes(t.localUrl)?assetPrefix+t.localUrl.slice(2):null;
  };
  const render=()=>{
    const p=items[index];
    if(!p)return;
    const url=source(p);
    title.textContent=p.brand+' · '+p.model;
    position.textContent=(index+1)+' / '+items.length;
    prev.disabled=items.length<2;next.disabled=items.length<2;
    // An exact-model product sheet usually has one approved photograph;
    // keep disabled gallery arrows out of its mobile purchase experience.
    prev.hidden=items.length<2;next.hidden=items.length<2;position.hidden=items.length<2;
    expanded=false;canvas.classList.remove('am-photo-expanded');
    zoom.textContent='Agrandir ×2';zoom.setAttribute('aria-pressed','false');zoom.disabled=true;
    photo.hidden=true;loaded=false;message.hidden=false;
    message.textContent=url?'Chargement de la photographie…':'Photographie indisponible. Consultez le fabricant.';
    photo.alt='Photographie authentique de '+p.brand+' '+p.model;
    if(url){photo.onload=()=>{loaded=true;photo.hidden=false;message.hidden=true;zoom.disabled=false};
      photo.onerror=()=>{loaded=false;photo.hidden=true;zoom.disabled=true;message.hidden=false;message.textContent='Photo indisponible. Consultez la source du modèle.'};
      photo.src=url;
    }else photo.removeAttribute('src');
    const raw=p.officialUrl;
    link.textContent=p.brand==='SKMEI'?'Voir le modèle chez le vendeur ↗':'Voir le modèle chez le fabricant ↗';
    try{const u=new URL(raw);link.href=u.protocol==='https:'?u.href:'#'}catch(_){link.href='#'}
  };
  const navigate=delta=>{if(items.length<2)return;index=(index+delta+items.length)%items.length;render()};
  close.addEventListener('click',()=>dialog.close());
  prev.addEventListener('click',()=>navigate(-1));
  next.addEventListener('click',()=>navigate(1));
  const toggleZoom=()=>{
    if(!loaded)return;
    expanded=!expanded;
    canvas.classList.toggle('am-photo-expanded',expanded);
    zoom.textContent=expanded?'Réduire ×1':'Agrandir ×2';
    zoom.setAttribute('aria-pressed',String(expanded));
    if(!expanded){
      canvas.scrollLeft=0;
      canvas.scrollTop=0;
      return;
    }
    // Open on the centre of the actual watch rather than the top-left corner
    // of a 2x photo. Both axes remain scrollable with mouse or touch.
    requestAnimationFrame(()=>{
      if(!expanded||!dialog.open)return;
      canvas.scrollLeft=(canvas.scrollWidth-canvas.clientWidth)/2;
      canvas.scrollTop=(canvas.scrollHeight-canvas.clientHeight)/2;
    });
  };
  zoom.addEventListener('click',toggleZoom);
  // A watch photograph itself is a discoverable zoom target on touch and
  // desktop. The adjacent labelled button remains keyboard accessible.
  photo.addEventListener('click',toggleZoom);
  dialog.addEventListener('click',event=>{if(event.target===dialog)dialog.close()});
  dialog.addEventListener('keydown',event=>{
    if(event.key==='ArrowLeft'){event.preventDefault();navigate(-1)}
    if(event.key==='ArrowRight'){event.preventDefault();navigate(1)}
  });
  canvas.addEventListener('touchstart',event=>{if(event.touches.length===1)initialTouch=event.touches[0].clientX},{passive:true});
  canvas.addEventListener('touchend',event=>{
    if(initialTouch===null||expanded||!event.changedTouches.length){initialTouch=null;return}
    const delta=event.changedTouches[0].clientX-initialTouch;initialTouch=null;
    if(Math.abs(delta)>65)navigate(delta>0?-1:1);
  },{passive:true});
  dialog.addEventListener('close',()=>{photo.onload=null;photo.onerror=null;expanded=false;canvas.classList.remove('am-photo-expanded')});
  document.body.append(dialog);
  window.AtelierPhoto={
    open(collection,id,{assetPrefix:requestedPrefix='./'}={}){
      if(!Array.isArray(collection)||!collection.length)return;
      items=collection.filter(p=>p&&typeof p.id==='string'&&typeof p.brand==='string'&&typeof p.model==='string');
      if(!items.length)return;
      // Only known same-origin roots can be selected. Never accept a caller URL.
      assetPrefix=requestedPrefix==='../'?'../':'./';
      index=Math.max(0,items.findIndex(p=>p.id===id));
      render();
      if(typeof dialog.showModal==='function'&&!dialog.open)dialog.showModal();
    }
  };
})();

/* Atelier Montres — URL-shareable, source-backed watch filters.
 * All 37 static cards remain crawlable and visible without JavaScript.
 * Search text is never sent to a server by this script; copying/sharing an
 * explicit URL is a visitor action, not a background analytics event. */
(() => {
  'use strict';
  const form=document.getElementById('am-pick-filters');
  const grid=document.getElementById('am-picks-list');
  if(!form||!grid)return;
  const cards=[...grid.querySelectorAll('.am-pick-card[data-pick-id]')];
  const sections=[...grid.querySelectorAll('.am-picks-tier')];
  const count=document.getElementById('am-pick-filter-count');
  const empty=document.getElementById('am-pick-filter-empty');
  const query=form.elements.namedItem('recherche');
  const style=form.elements.namedItem('style');
  const movement=form.elements.namedItem('mouvement');
  const tier=form.elements.namedItem('gamme');
  const photoOnly=form.elements.namedItem('photo-publiee');
  const matchOnly=form.elements.namedItem('asin-documente');
  const share=document.getElementById('am-pick-share');
  const shareStatus=document.getElementById('am-pick-share-status');
  const manual=document.getElementById('am-pick-share-manual');
  const active=document.getElementById('am-pick-active');
  const activeChips=document.getElementById('am-pick-active-chips');
  const clearActive=document.getElementById('am-pick-active-clear');
  if(!cards.length||!sections.length||!count||!empty||!query||!style||
    !movement||!tier||!photoOnly||!matchOnly||!share||!shareStatus||!manual
    ||!active||!activeChips||!clearActive)return;

  const allowed={
    tier:new Set(['essential','signature','prestige']),
    style:new Set(['sport','steel','dress','retro','compact']),
    movement:new Set(['automatic','quartz','solar'])
  };
  const normalize=value=>String(value||'').toLocaleLowerCase('fr-FR')
    .normalize('NFD').replace(/[\u0300-\u036f]/g,'').trim();
  const haystack=new Map(cards.map(card=>[card,normalize(card.dataset.pickSearch||card.textContent)]));
  const initial=location.search.length<=850?new URLSearchParams(location.search):new URLSearchParams();
  const unique=name=>initial.getAll(name).length===1?initial.get(name):null;
  const savedQuery=unique('q');
  if(savedQuery&&savedQuery.length<=80)query.value=savedQuery;
  for(const [name,control] of [['tier',tier],['style',style],['movement',movement]]){
    const value=unique(name);
    if(value&&allowed[name].has(value))control.value=value;
  }
  photoOnly.checked=unique('photo')==='1';
  matchOnly.checked=unique('asin')==='1';

  const chipControls={
    q:{label:'Recherche',control:query},
    tier:{label:'Gamme',control:tier},
    style:{label:'Style',control:style},
    movement:{label:'Mouvement',control:movement},
    photo:{label:'Photo réelle',control:photoOnly},
    asin:{label:'Référence Amazon',control:matchOnly}
  };
  let previousChips='';
  const updateChips=()=>{
    const selected=Object.entries(chipControls).flatMap(([key,{label,control}])=>{
      const value=key==='photo'||key==='asin'
        ?(control.checked?'Oui':''):control.value.trim();
      if(!value)return [];
      const display=control.tagName==='SELECT'
        ?control.selectedOptions[0]?.textContent||value:value;
      return [{key,label,display}];
    });
    active.hidden=selected.length===0;
    const signature=JSON.stringify(selected);
    // Keep a pressed chip alive through the blur/change/click sequence.
    if(signature===previousChips)return;
    previousChips=signature;
    const buttons=selected.map(({key,label,display})=>{
      const button=document.createElement('button');
      button.type='button';
      button.className='am-pick-chip';
      button.dataset.removeFilter=key;
      button.textContent=label+' : '+display+' ×';
      button.setAttribute('aria-label','Retirer le filtre '+label+' : '+display);
      return button;
    });
    activeChips.replaceChildren(...buttons);
  };
  const selectionUrl=()=>{
    const url=new URL(location.pathname,location.origin);
    const search=query.value.trim();
    if(search)url.searchParams.set('q',search.slice(0,80));
    if(tier.value&&allowed.tier.has(tier.value))url.searchParams.set('tier',tier.value);
    if(style.value&&allowed.style.has(style.value))url.searchParams.set('style',style.value);
    if(movement.value&&allowed.movement.has(movement.value))url.searchParams.set('movement',movement.value);
    if(photoOnly.checked)url.searchParams.set('photo','1');
    if(matchOnly.checked)url.searchParams.set('asin','1');
    return url;
  };
  const apply=(updateUrl=true)=>{
    const tokens=normalize(query.value).split(/\s+/).filter(Boolean);
    let shown=0;
    for(const card of cards){
      const matches=(!style.value||card.dataset.pickStyle===style.value)
        &&(!movement.value||card.dataset.pickMovement===movement.value)
        &&(!tier.value||card.dataset.pickTier===tier.value)
        &&(!photoOnly.checked||card.dataset.pickPhoto==='yes')
        &&(!matchOnly.checked||card.dataset.pickMatch==='yes')
        &&tokens.every(token=>haystack.get(card).includes(token));
      card.hidden=!matches;
      if(matches)shown++;
    }
    for(const section of sections){
      section.hidden=![...section.querySelectorAll('.am-pick-card')].some(card=>!card.hidden);
    }
    count.textContent=shown+' modèle'+(shown>1?'s':'')+' sur '+cards.length;
    empty.hidden=shown!==0;
    updateChips();
    if(updateUrl){
      const url=selectionUrl();
      history.replaceState(null,'',url.pathname+url.search+location.hash);
      shareStatus.textContent='';
      manual.hidden=true;
    }
  };

  activeChips.addEventListener('click',event=>{
    const button=event.target.closest('button[data-remove-filter]');
    if(!button||!Object.hasOwn(chipControls,button.dataset.removeFilter))return;
    const {control}=chipControls[button.dataset.removeFilter];
    if(control.type==='checkbox')control.checked=false;
    else control.value='';
    apply();
    control.focus({preventScroll:true});
  });
  clearActive.addEventListener('click',()=>{
    form.reset();
    query.focus({preventScroll:true});
  });
  form.hidden=false;
  share.hidden=false;
  form.addEventListener('input',()=>apply());
  form.addEventListener('change',()=>apply());
  form.addEventListener('reset',event=>{
    // Reset is explicit: do not depend on browser reset event ordering.
    event.preventDefault();
    query.value='';
    style.value='';
    movement.value='';
    tier.value='';
    photoOnly.checked=false;
    matchOnly.checked=false;
    apply();
  });
  // Existing tier shortcuts should reveal every section before navigating.
  document.querySelectorAll('.am-picks-tier-nav a[href^="#gamme-"]').forEach(anchor=>{
    anchor.addEventListener('click',()=>form.reset());
  });
  share.addEventListener('click',async()=>{
    const url=selectionUrl();
    url.hash='#am-pick-filter-count';
    const address=url.href;
    manual.hidden=true;
    shareStatus.textContent='';
    if(typeof navigator.share==='function'){
      try{
        await navigator.share({title:'Ma sélection · Atelier Montres',url:address});
        shareStatus.textContent='Sélection partagée.';
        return;
      }catch(err){
        if(err?.name==='AbortError'){
          shareStatus.textContent='Partage annulé.';
          return;
        }
      }
    }
    try{
      if(typeof navigator.clipboard?.writeText==='function'){
        await navigator.clipboard.writeText(address);
        shareStatus.textContent='Lien de sélection copié.';
        return;
      }
    }catch(_){}
    manual.value=address;
    manual.hidden=false;
    manual.focus({preventScroll:true});
    manual.select();
    shareStatus.textContent='Copiez le lien sélectionné pour partager ces critères.';
  });
  // Never replace history on initial load: unknown incoming campaign params
  // are not read by the filters and must not silently cause a tracked event.
  apply(false);
})();

/* Atelier Montres — source-backed discovery, no unauthorized product photos.
   The artwork is deliberately typographic, never an exact-model rendering. */
.am-picks{background:#f1f0e9;padding:clamp(54px,6vw,88px) 0;border-top:1px solid #dbddcf;border-bottom:1px solid #d5dacd}
.am-picks-heading{max-width:920px;margin-bottom:26px}
.am-picks-heading .overline{color:#846336}
.am-picks-heading h2,.am-picks-intro h1{color:#203a2b;font:400 clamp(31px,4.8vw,54px)/1.16 Georgia,serif;letter-spacing:-.032em;margin:11px 0 16px}
.am-picks-heading>p:last-child,.am-picks-intro>p{max-width:850px;color:#435949;font:400 16px/1.75 system-ui,sans-serif}
.am-picks-grid{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;align-items:stretch}
.am-pick-card{min-width:0;display:flex;flex-direction:column;border:1px solid #d7d8ce;border-radius:8px;overflow:hidden;background:#fffdf9;box-shadow:0 15px 38px #203b2910;isolation:isolate}
.am-pick-visual{--visual-bg:#173c32;--visual-light:#d9d6bc;--visual-ornament:#c3a978;position:relative;isolation:isolate;display:flex;flex-direction:column;align-items:flex-start;justify-content:flex-end;gap:8px;overflow:hidden;aspect-ratio:1.35/1;min-height:175px;padding:22px;color:#fff;background:radial-gradient(ellipse at 76% 34%,#4c6551 0%,var(--visual-bg) 70%)}
.am-pick-retro .am-pick-visual{--visual-bg:#354a52;--visual-light:#f2e5bc;--visual-ornament:#d0cfca}
.am-pick-compact .am-pick-visual{--visual-bg:#674558;--visual-light:#f4dae0;--visual-ornament:#e2a6bd}
.am-pick-dress .am-pick-visual{--visual-bg:#504838;--visual-light:#f8e9b6;--visual-ornament:#e4d4a7}
.am-pick-steel .am-pick-visual{--visual-bg:#2d4555;--visual-light:#dce7f0;--visual-ornament:#b5d1d5}
.am-pick-visual::before{content:'';position:absolute;top:16%;right:6%;width:145px;max-width:48%;aspect-ratio:1;border:9px solid var(--visual-ornament);border-radius:50%;opacity:.16;transform:rotate(-25deg);box-shadow:0 0 0 18px #ffffff20,0 0 0 31px #ffffff13;pointer-events:none;z-index:-1}
.am-pick-visual-top{align-self:flex-start;border:1px solid #ffffff7a;border-radius:99px;padding:5px 10px;color:#fff7ed;font:750 11px/1.5 system-ui,sans-serif}
.am-pick-visual-name{margin-top:auto;color:var(--visual-light);font:750 13px/1.35 system-ui,sans-serif;letter-spacing:.11em;text-transform:uppercase;overflow-wrap:anywhere}
.am-pick-visual-ref{color:#fff;font:400 clamp(24px,2.4vw,34px)/1.17 Georgia,serif;letter-spacing:-.015em;overflow-wrap:anywhere}
.am-pick-visual-caption{color:#ede9df;font:400 11px/1.5 system-ui,sans-serif;opacity:.9}
.am-pick-content{padding:22px;display:flex;flex:1;flex-direction:column;align-items:stretch;gap:11px}
.am-pick-kicker{display:flex;align-items:center;justify-content:space-between;flex-wrap:wrap;gap:7px;margin:0;color:#6b5536;font:750 11px/1.4 system-ui,sans-serif;text-transform:uppercase;letter-spacing:.035em}
.am-pick-kicker span:last-child{background:#eff2ea;color:#355744;border-radius:3px;padding:5px 8px}
.am-pick-content h3{color:#243f2d;font:400 clamp(22px,2.5vw,29px)/1.25 Georgia,serif;margin:0;overflow-wrap:anywhere}
.am-pick-lead{font:400 14px/1.7 system-ui,sans-serif;color:#3f5645;margin:0}
.am-pick-specs{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px;margin:3px 0 0}
.am-pick-specs div{min-width:0;border-top:1px solid #d8d9cf;padding-top:8px}
.am-pick-specs dt{color:#627568;font:600 12px/1.45 system-ui,sans-serif;margin:0 0 4px}
.am-pick-specs dd{margin:0;color:#223c2e;font:700 13px/1.5 system-ui,sans-serif;overflow-wrap:anywhere}
.am-pick-caution{font:400 13px/1.65 system-ui,sans-serif;color:#526454;margin:0}
.am-pick-actions{display:grid;gap:8px;margin-top:auto;padding-top:8px}
