.selector-public .selector-hero-secondary{
  display:inline-flex;min-height:48px;align-items:center;
  font:700 13px/1.5 system-ui,sans-serif;color:#f0dab7;
  text-decoration:underline;text-underline-offset:5px
}
.selector-public .selector-hero-secondary:hover{color:#fff}
.selector-public .selector-hero .selector-hero-note{
  max-width:690px;margin:25px 0 0;font-size:13px;line-height:1.7;
  color:#e3e8dc
}
.selector-public .selector-nojs{
  padding:19px 23px;margin:18px 0;border:1px solid #c7bca6;
  background:#fffdf7;color:#284433;font:500 15px/1.65 system-ui,sans-serif
}
.selector-public .selector-nojs a{color:#21533b;font-weight:700}
@media(max-width:820px){
  .selector-public .header-inner{
    height:auto;min-height:82px;display:flex;flex-wrap:wrap;
    gap:9px 16px;padding-block:14px
  }
  .selector-public .header-inner>.brand{flex:1 1 100%}
  .selector-public .navigation{
    flex:1 1 100%;min-width:0;gap:13px;
    overflow-x:auto;overscroll-behavior-x:contain;
    -webkit-overflow-scrolling:touch;scrollbar-width:thin;
    flex-wrap:nowrap
  }
  .selector-public .navigation a{
    flex:0 0 auto;display:inline-flex;align-items:center;
    min-height:44px;padding:8px 3px
  }
  .selector-public .header-inner .tag{display:none}
}
@media(max-width:620px){
  .selector-public .selector-hero::before{
    right:-48%;top:-13%;width:85vw
  }
  .selector-public .selector-hero-actions{
    display:flex;flex-direction:column;align-items:stretch;gap:12px
  }
  .selector-public .selector-hero-actions .button{width:100%}
  .selector-public .selector-hero-secondary{justify-content:center;text-align:center}
}
@media(prefers-reduced-motion:reduce){
  .selector-public .selector-hero-actions .button{
    transition:none
  }
  .selector-public .selector-hero-actions .button:hover{
    transform:none
  }
}
